     1	import { useCallback, useMemo } from 'react';
     2	import { useContentfulEntries } from './useContentful';
     3	import type { UiCopyEntry } from '../types/contentful';
     4	
     5	type UseUiCopyReturn = {
     6	  /**
     7	   * Returns the CMS value for `key`, or `fallback` while the fetch is loading, on fetch
     8	   * error, or when no `uiCopy` entry with that key exists yet.
     9	   */
    10	  t: (key: string, fallback: string) => string;
    11	  isLoading: boolean;
    12	};
    13	
    14	/**
    15	 * Bulk-fetches every `uiCopy` entry in one Delivery API call (`content_type=uiCopy`) and
    16	 * exposes it as a key→value lookup — creating N entries in Contentful costs one call, not N.
    17	 *
    18	 * Call-site fallback text is deliberate, not just a loading placeholder: unlike structural
    19	 * content (e.g. FooterContainer's footerConfig, which renders nothing rather than substitute
    20	 * placeholder content), losing a button label or a status message to a Contentful outage
    21	 * should never blank a control — the fallback keeps every call site self-contained and
    22	 * functional even before a matching entry exists in Contentful.
    23	 *
    24	 * @returns `t` lookup function plus `isLoading`
    25	 */
    26	export const useUiCopy = (): UseUiCopyReturn => {
    27	  const { data, isLoading } = useContentfulEntries<UiCopyEntry>('uiCopy');
    28	
    29	  const copyMap = useMemo(() => {
    30	    const map = new Map<string, string>();
    31	    (data ?? []).forEach((entry) => {
    32	      map.set(entry.fields.key, entry.fields.value);
    33	    });
    34	    return map;
    35	  }, [data]);
    36	
    37	  const t = useCallback((key: string, fallback: string): string => copyMap.get(key) ?? fallback, [copyMap]);
    38	
    39	  return { t, isLoading };
    40	};

