     7	import React from 'react';
     8	import { ChakraProvider } from '@salesforce/retail-react-app/app/components/shared/ui';
     9	import { ZimmTokensGlobal } from '../../theme/zimmTokensGlobal';
    10	import { ZimmFontFace } from '../../theme/fontFace';
    11	import { UiCopyProvider } from '../uiCopyProvider';
    12	
    13	// Removes focus for non-keyboard interactions for the whole application
    14	import 'focus-visible/dist/focus-visible';
    15	
    16	import theme from '../../theme';
    17	import { MultiSiteProvider, StoreLocatorProvider } from '@salesforce/retail-react-app/app/contexts';
    18	import {
    19	  resolveSiteFromUrl,
    20	  getParamsFromPath,
    21	  getSites,
    22	  getLocaleByReference,
    23	} from '@salesforce/retail-react-app/app/utils/site-utils';
    24	import { getConfig } from '@salesforce/pwa-kit-runtime/utils/ssr-config';
    25	import { getEnvBasePath, slasPrivateProxyPath } from '@salesforce/pwa-kit-runtime/utils/ssr-namespace-paths';
    26	import { createUrlTemplate } from '@salesforce/retail-react-app/app/utils/url';
    27	import createLogger from '@salesforce/pwa-kit-runtime/utils/logger-factory';
    28	import { getPasswordlessCallbackUrl } from '@salesforce/retail-react-app/app/utils/auth-utils';
    29	
    30	import { CommerceApiProvider } from '@salesforce/commerce-sdk-react';
    31	import { withReactQuery } from '@salesforce/pwa-kit-react-sdk/ssr/universal/components/with-react-query';
    32	import { useCorrelationId } from '@salesforce/pwa-kit-react-sdk/ssr/universal/hooks';
    33	import { getAppOrigin } from '@salesforce/pwa-kit-react-sdk/utils/url';
    34	import { ReactQueryDevtools } from '@tanstack/react-query-devtools';
    35	import { generateSfdcUserAgent } from '@salesforce/retail-react-app/app/utils/sfdc-user-agent-utils';
    36	import {
    37	  DEFAULT_DNT_STATE,
    38	  STORE_LOCATOR_RADIUS,
    39	  STORE_LOCATOR_RADIUS_UNIT,
    40	  STORE_LOCATOR_DEFAULT_COUNTRY,
    41	  STORE_LOCATOR_DEFAULT_COUNTRY_CODE,
    42	  STORE_LOCATOR_DEFAULT_POSTAL_CODE,
    43	  STORE_LOCATOR_DEFAULT_PAGE_SIZE,
    44	  STORE_LOCATOR_SUPPORTED_COUNTRIES,
    45	} from '@salesforce/retail-react-app/app/constants';
    46	import { ContentfulLivePreviewProvider } from '@contentful/live-preview/react';
    47	
    48	const sfdcUserAgent = generateSfdcUserAgent();
    49	
    50	type SiteLocale = {
    51	  id: string;
    52	  alias?: string;
    53	  preferredCurrency: string;
    54	};
    55	
    56	// sfccSiteId overrides the SFCC Commerce API siteId for PWA sites whose ID differs from the
    57	// SFCC site ID (e.g. ZimmermannEUfr → SFCC ZimmermannEU).
    58	type SiteConfig = {
    59	  id: string;
    60	  sfccSiteId?: string;
    61	  alias?: string;
    62	  l10n: {
    63	    defaultLocale: string;
    64	    supportedLocales: SiteLocale[];
    65	  };
    66	};
    67	
    68	type AppLocals = {
    69	  appConfig?: {
    70	    commerceAPI: {
    71	      proxyPath: string;
    72	      parameters: {
    73	        shortCode: string;
    74	        clientId: string;
    75	        organizationId: string;
    76	        siteId?: string;
    77	      };
    78	    };
    79	    login?: {
    80	      passwordless?: {
    81	        callbackURI?: string;
    82	      };
    83	    };
    84	    einsteinAPI?: unknown;
    85	  };
    86	  site?: Pick<SiteConfig, 'id' | 'sfccSiteId' | 'alias'>;
    87	  locale?: Pick<SiteLocale, 'id' | 'preferredCurrency'>;
    88	  buildUrl?: ReturnType<typeof createUrlTemplate>;
    89	  originalUrl?: string;
    90	};
    91	
    92	type AppConfigProps = {
    93	  children: React.ReactNode;
    94	  locals?: AppLocals;
    95	};
    96	
    97	/**
    98	 * Use the AppConfig component to inject extra arguments into the getProps
    99	 * methods for all Route Components in the app – typically you'd want to do this
   100	 * to inject a connector instance that can be used in all Pages.
   101	 *
   102	 * You can also use the AppConfig to configure a state-management library such
   103	 * as Redux, or Mobx, if you like.
   104	 */
   105	const AppConfig = ({ children, locals = {} }: AppConfigProps): React.ReactElement => {
   106	  const { correlationId } = useCorrelationId();
   107	  const headers = {
   108	    'correlation-id': correlationId,
   109	    sfdc_user_agent: sfdcUserAgent,
   110	  };
   111	
   112	  if (!locals.appConfig) throw new Error('AppConfig: locals.appConfig is required');
   113	  const commerceApiConfig = locals.appConfig.commerceAPI;
   114	  const locale = locals.locale?.id ?? 'en-US';
   115	
   116	  const appOrigin = getAppOrigin();
   117	  const passwordlessCallbackURI = getPasswordlessCallbackUrl(locals.appConfig?.login?.passwordless?.callbackURI);
   118	
   119	  const storeLocatorConfig = {
   120	    radius: STORE_LOCATOR_RADIUS,
   121	    radiusUnit: STORE_LOCATOR_RADIUS_UNIT,
   122	    defaultCountry: STORE_LOCATOR_DEFAULT_COUNTRY,
   123	    defaultCountryCode: STORE_LOCATOR_DEFAULT_COUNTRY_CODE,
   124	    defaultPostalCode: STORE_LOCATOR_DEFAULT_POSTAL_CODE,
   125	    defaultPageSize: STORE_LOCATOR_DEFAULT_PAGE_SIZE,
   126	    supportedCountries: STORE_LOCATOR_SUPPORTED_COUNTRIES,
   127	  };
   128	
   129	  // Set absolute uris for CommerceApiProvider proxies and callbacks
   130	  const redirectURI = `${appOrigin}${getEnvBasePath()}/callback`;
   131	  const proxy = `${appOrigin}${getEnvBasePath()}${commerceApiConfig.proxyPath}`;
   132	  const slasPrivateClientProxyEndpoint = `${appOrigin}${getEnvBasePath()}${slasPrivateProxyPath}`;
   133	
   134	  return (
   135	    <CommerceApiProvider
   136	      shortCode={commerceApiConfig.parameters.shortCode}
   137	      clientId={commerceApiConfig.parameters.clientId}
   138	      organizationId={commerceApiConfig.parameters.organizationId}
   139	      siteId={locals.site?.sfccSiteId ?? locals.site?.id ?? ''}
   140	      locale={locale}
   141	      currency={locals.locale?.preferredCurrency ?? ''}
   142	      redirectURI={redirectURI}
   143	      proxy={proxy}
   144	      headers={headers}
   145	      defaultDnt={DEFAULT_DNT_STATE}
   146	      logger={createLogger({ packageName: 'commerce-sdk-react' })}
   147	      passwordlessLoginCallbackURI={passwordlessCallbackURI}
   148	      // Set 'enablePWAKitPrivateClient' to true to use SLAS private client login flows.
   149	      // Make sure to also enable useSLASPrivateClient in ssr.js when enabling this setting.
   150	      enablePWAKitPrivateClient={true}
   151	      privateClientProxyEndpoint={slasPrivateClientProxyEndpoint}
   152	      // Uncomment 'hybridAuthEnabled' if the current site has Hybrid Auth enabled. Do NOT set this flag for hybrid storefronts using Plugin SLAS.
   153	      // hybridAuthEnabled={true}
   154	    >
   155	      <MultiSiteProvider site={locals.site} locale={locals.locale} buildUrl={locals.buildUrl}>
   156	        <StoreLocatorProvider config={storeLocatorConfig}>
   157	          <ContentfulLivePreviewProvider locale={locale} enableInspectorMode enableLiveUpdates>
   158	            <ChakraProvider theme={theme}>
   159	              <ZimmFontFace />
   160	              <ZimmTokensGlobal />
   161	              <UiCopyProvider>{children}</UiCopyProvider>
   162	            </ChakraProvider>
   163	          </ContentfulLivePreviewProvider>
   164	        </StoreLocatorProvider>
   165	      </MultiSiteProvider>
   166	      <ReactQueryDevtools />
   167	    </CommerceApiProvider>
   168	  );
   169	};
   170	
   171	AppConfig.restore = (locals: AppLocals = {}): void => {
   172	  const path =
   173	    typeof window === 'undefined' ? locals.originalUrl ?? '/' : `${window.location.pathname}${window.location.search}`;
   174	
   175	  // resolveSiteFromUrl only matches a site alias/ID in the URL. When url.site is 'none' the site
   176	  // segment is absent, so it always falls back to the defaultSite. In that case, find the real site
   177	  // by matching the locale alias from the URL against each site's supportedLocales.
   178	  const defaultResolved = resolveSiteFromUrl(path);
   179	  const { localeRef } = getParamsFromPath(path);
   180	  type SupportedLocale = { id: string; alias?: string };
   181	  // sfccSiteId overrides the SFCC Commerce API siteId for PWA sites that don't share their ID
   182	  // with their SFCC counterpart (e.g. ZimmermannEUfr → SFCC ZimmermannEU).
   183	  type Site = {
   184	    id: string;
   185	    sfccSiteId?: string;
   186	    alias?: string;
   187	    l10n: { defaultLocale: string; supportedLocales: SupportedLocale[] };
   188	  };
   189	  const site: Site = localeRef
   190	    ? (getSites() as Site[]).find((s) =>
   191	        s.l10n.supportedLocales.some((l) => l.alias === localeRef || l.id === localeRef),
   192	      ) ?? defaultResolved
   193	    : defaultResolved;
   194	
   195	  // resolveLocaleFromUrl also calls resolveSiteFromUrl internally, so it would return the wrong
   196	  // site too. Resolve the locale directly from the site we already found above.
   197	  const locale = (getLocaleByReference(site, localeRef ?? site.l10n.defaultLocale) ??
   198	    getLocaleByReference(site, site.l10n.defaultLocale)) as SiteLocale;
   199	
   200	  const { app: appConfig } = getConfig() as { app: NonNullable<AppLocals['appConfig']> };
   201	  const apiConfig = {
   202	    ...appConfig.commerceAPI,
   203	    einsteinConfig: appConfig.einsteinAPI,
   204	  };
   205	
   206	  apiConfig.parameters.siteId = site.sfccSiteId ?? site.id;
   207	
   208	  locals.buildUrl = createUrlTemplate(appConfig, site.alias || site.id, locale.alias || locale.id);
   209	  locals.site = site;
   210	  locals.locale = locale;
   211	  locals.appConfig = appConfig;
   212	};
   213	
   214	AppConfig.freeze = (): undefined => undefined;
   215	
   216	AppConfig.extraGetPropsArgs = (locals: AppLocals = {}): Record<string, unknown> => {
   217	  return {
   218	    buildUrl: locals.buildUrl,
   219	    site: locals.site,
   220	    locale: locals.locale,
   221	  };
   222	};
   223	
   224	const isServerSide = typeof window === 'undefined';
   225	
   226	// Recommended settings for PWA-Kit usages.
   227	// NOTE: they will be applied on both server and client side.
   228	// retry is always disabled on server side regardless of the value from the options
   229	const options = {
   230	  queryClientConfig: {
   231	    defaultOptions: {
   232	      queries: {
   233	        retry: false,
   234	        refetchOnWindowFocus: false,
   235	        staleTime: 10 * 1000,
   236	        ...(isServerSide ? { retryOnMount: false } : {}),
   237	      },
   238	      mutations: {
   239	        retry: false,
   240	      },
   241	    },
   242	  },
   243	};
   244	
   245	export default withReactQuery(AppConfig, options);

